import { route, HttpError } from '@/lib/server/http';
import { readJson, str, email } from '@/lib/server/validate';
import { rateLimit } from '@/lib/server/rateLimit';
import { anonClient, adminClient } from '@/lib/server/supabase';

export const POST = route(async (req) => {
  rateLimit(req, 'signup');
  const body = await readJson(req);
  const name = str(body.name, '이름', 1, 50);
  const mail = email(body.email);
  const password = str(body.password, '비밀번호', 8, 72);
  const { data, error } = await anonClient().auth.signUp({ email: mail, password });
  if (error || !data.user) throw new HttpError(400, error?.message ?? '회원가입에 실패했습니다.');
  const { error: insertError } = await adminClient().from('members').insert({ id: data.user.id, name });
  if (insertError) throw insertError;
  return Response.json({ ok: true }, { status: 201 });
});

