'use client';
import { useState } from 'react';
import { useRouter } from 'next/navigation';
import { api, setToken } from '@/services/api';

export default function LoginPage() {
  const router = useRouter();
  const [mode, setMode] = useState<'login' | 'signup'>('login');
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');

  async function submit(e: React.FormEvent) {
    e.preventDefault();
    setError('');
    try {
      if (mode === 'signup') await api.signup(name, email, password);
      setToken((await api.login(email, password)).token);
      router.push('/book');
    } catch (err) {
      setError((err as Error).message);
    }
  }

  return (
    <form onSubmit={submit}>
      <h1>PT 예약</h1>
      {error && <p className="error" role="alert">{error}</p>}
      {mode === 'signup' && <input placeholder="이름" value={name} onChange={(e) => setName(e.target.value)} />}
      <input type="email" placeholder="이메일" value={email} onChange={(e) => setEmail(e.target.value)} />
      <input type="password" placeholder="비밀번호 (8자 이상)" value={password} onChange={(e) => setPassword(e.target.value)} />
      <button type="submit">{mode === 'login' ? '로그인' : '회원가입'}</button>
      <button type="button" style={{ background: '#666' }} onClick={() => setMode(mode === 'login' ? 'signup' : 'login')}>
        {mode === 'login' ? '회원가입하기' : '로그인으로'}
      </button>
    </form>
  );
}

